PHONES = {"dana": "+18135550141", "ava": "+18135550142", "sam": "+17275550160", "noah": "+16565550118",
          "mia": "+18135550190", "lee": "+17275550150", "pat": "+18135550170", "owen": "+16565550133",
          "kids": "+18135550125", "zoe": "+17275550107", "theo": "+18135550111", "ruby": "+16565550164",
          "finn": "+17275550182"}


# ---------------------------------------------------------------- one store, as of `now`

_builds = 0


def build(now: datetime) -> dict:
    """Plays the story as of `now` (practice time) into a fresh database and returns what the
    routes answer at that moment: every lead (masked) and each lead's history."""
    global _builds
    _builds += 1                             # a fresh database every time, also for the same `now`
    os.environ["LEADS_DB_PATH"] = os.path.join(_tmp, f"leads-{_builds}-{now.strftime('%Y%m%d-%H%M%S')}.sqlite")
    seq = iter(range(10_000))
    leads._new_id = lambda: "L" + hashlib.sha1(f"katie-fixture-{next(seq)}".encode()).hexdigest()[:10]

    today = now.date()
    anchor = today
    while anchor.weekday() >= 5:            # a weekend "now": day 0 of the story is the Friday before
        anchor -= timedelta(days=1)

    def bd(n: int, hour: int, minute: int = 0) -> datetime:
        """Practice time `n` business days from day 0 (negative = before; positive counts from today)."""
        d = anchor if n <= 0 else today
        step = 1 if n > 0 else -1
        left = abs(n)
        while left:
            d += timedelta(days=step)
            if d.weekday() < 5:
                left -= 1
        return datetime(d.year, d.month, d.day, hour, minute, tzinfo=TZ)

    def iso(dt: datetime) -> str:
        return dt.isoformat(timespec="seconds")

    def label(dt: datetime) -> str:
        return leads._label_of(iso(dt))

    Q = quotes()
    ids: dict[str, str] = {}
    steps: list[tuple[datetime, int, object]] = []

    def at(when: datetime, fn) -> None:
        assert when <= now, f"a step after now: {when} > {now}"
        steps.append((when, len(steps), fn))

    def need(v, what: str):
        assert v, f"the backend dropped: {what}"
        return v

    def quote(name: str, when: datetime, *, phone: str, lang: str = "en", basis: str = "verbal_yes_on_call",
              first: str = "", appt: tuple[str, datetime] | None = None) -> None:
        def run():
            row = need(leads.quoted(f"fixture-{name}", phone=phone, lang=lang, consent_basis=basis,
                                    first_name=first or name.capitalize(), quote=Q[name], practice_slug=SLUG,
                                    appointment_id=appt[0] if appt else "",
                                    appointment_start=iso(appt[1]) if appt else "",
                                    booked_ts=when.timestamp(), now=when.timestamp()), f"quote for {name}")
            ids[name] = row["lead_id"]
        at(when, run)

    def tap(name: str, when: datetime, action: str, *, note: str = "", slot: str = "") -> None:
        at(when, lambda: need(leads.coordinator(ids[name], action, who=WHO, note=note, slot_label=slot,
                                                now=when.timestamp()), f"{action} on {name}"))

    def text_in(key: str, when: datetime, kind: str) -> None:
        at(when, lambda: need(leads.touched(PHONES[key], f"text in: {kind}", direction="in", now=when.timestamp()),
                              f"text in on {key}"))

    def text_out(key: str, when: datetime) -> None:
        at(when, lambda: need(leads.touched(PHONES[key], "text out", direction="out", now=when.timestamp()),
                              f"text out on {key}"))

    # Dana: quoted, Katie booked the exam on a later call, the family cancelled it by text. Pool A.
    quote("dana", bd(-6, 10, 12), phone=PHONES["dana"])
    dana_exam = bd(-1, 14, 30)
    at(bd(-5, 16, 40), lambda: need(leads.booked(PHONES["dana"], label(dana_exam), appointment_id="APPT-2291",
                                                 start=iso(dana_exam), source="call_booking", patient_name="Dana Whitlow",
                                                 now=bd(-5, 16, 40).timestamp()), "Dana's booking"))
    text_in("dana", bd(-2, 19, 4), "no")
    at(bd(-2, 19, 5), lambda: need(leads.cancelled(PHONES["dana"], label(dana_exam), source="sms_cancel",
                                                   now=bd(-2, 19, 5).timestamp()), "Dana's cancel"))

    # Ava (Spanish): quoted after the call had booked; nobody checked in, so the clock called it.
    ava_exam = bd(-1, 9, 0)
    quote("ava", bd(-4, 11, 30), phone=PHONES["ava"], lang="es", appt=("APPT-2304", ava_exam))
    sweep_at = ava_exam + timedelta(minutes=95)

    def sweep():
        got = leads.mark_missed_by_clock(now=sweep_at.timestamp())
        assert [l["lead_id"] for l in got] == [ids["ava"]], f"the sweep moved {[l['first_name'] for l in got]}"
    at(sweep_at, sweep)

    # Sam: the desk booked him by hand, he did not come, then he texted STOP.
    quote("sam", bd(-9, 9, 20), phone=PHONES["sam"])
    tap("sam", bd(-8, 15, 2), "booked", slot=bd(-5, 13, 0).strftime("%Y-%m-%dT%H:%M"))
    tap("sam", bd(-5, 15, 10), "missed")
    text_out("sam", bd(-4, 12, 0))
    text_in("sam", bd(-3, 18, 20), "stop")
    at(bd(-3, 18, 20) + timedelta(seconds=1),
       lambda: need(leads.stopped(PHONES["sam"], now=(bd(-3, 18, 20) + timedelta(seconds=1)).timestamp()), "Sam's STOP"))

    # Noah: quoted, then booked with Katie; confirmed by text this morning.
    quote("noah", bd(-2, 13, 45), phone=PHONES["noah"])
    noah_exam = bd(2, 8, 0)
    at(bd(-1, 17, 35), lambda: need(leads.booked(PHONES["noah"], label(noah_exam), appointment_id="APPT-2317",
                                                 start=iso(noah_exam), source="call_booking", patient_name="Noah Bellamy",
                                                 now=bd(-1, 17, 35).timestamp()), "Noah's booking"))
    text_out("noah", bd(0, 9, 2))
    text_in("noah", bd(0, 9, 15), "yes")

    # Mia (Spanish, consent on the consult page): quoted with tomorrow's exam already on the books.
    quote("mia", bd(-1, 15, 25), phone=PHONES["mia"], lang="es", basis="form_consent", appt=("APPT-2320", bd(1, 15, 20)))

    # Lee: booked at the quote; the schedule moved the exam later.
    quote("lee", bd(-3, 10, 5), phone=PHONES["lee"], appt=("APPT-2298", bd(1, 10, 0)))
    at(bd(-1, 12, 40), lambda: need(leads.mark_from_pms(ids["lee"], {"start_time": iso(bd(4, 10, 0))},
                                                        now=bd(-1, 12, 40).timestamp()), "Lee's moved exam"))

    # Pat: quoted well over a week ago, never booked.
    quote("pat", bd(-8, 14, 10), phone=PHONES["pat"], basis="verified_patient_on_file")
    text_in("pat", bd(-7, 8, 44), "other")

    # Owen: quoted today.
    quote("owen", bd(0, 11, 40), phone=PHONES["owen"])

    # Iris and Jude: two children on one number. A booking with no name moves neither (and the
    # history says so); the one with a name moves Jude.
    quote("iris", bd(-2, 9, 30), phone=PHONES["kids"])
    quote("jude", bd(-2, 9, 31), phone=PHONES["kids"])
    kids_exam = bd(3, 16, 0)

    def kids_no_name():
        got = leads.booked(PHONES["kids"], label(kids_exam), source="call_booking", now=bd(-1, 8, 50).timestamp())
        assert got == [], "a booking with no name must move nobody"
    at(bd(-1, 8, 50), kids_no_name)
    at(bd(-1, 8, 52), lambda: need(leads.booked(PHONES["kids"], label(kids_exam), appointment_id="APPT-2311",
                                                start=iso(kids_exam), source="call_booking", patient_name="Jude Marsh",
                                                now=bd(-1, 8, 52).timestamp()), "Jude's booking"))

    # Zoe: came in (the schedule's check-in); not started yet.
    zoe_exam = bd(-1, 8, 0)
    quote("zoe", bd(-5, 10, 0), phone=PHONES["zoe"], appt=("APPT-2281", zoe_exam))
    at(bd(-1, 8, 6), lambda: need(leads.mark_from_pms(ids["zoe"], {"checkin_at": iso(bd(-1, 8, 6))},
                                                      now=bd(-1, 8, 6).timestamp()), "Zoe's check-in"))
    tap("zoe", bd(-1, 8, 50), "note", note="Mom prefers morning visits")

    # Theo: the whole way through. Started.
    quote("theo", bd(-12, 13, 15), phone=PHONES["theo"])
    theo_exam = bd(-8, 11, 0)
    at(bd(-11, 9, 40), lambda: need(leads.booked(PHONES["theo"], label(theo_exam), appointment_id="APPT-2256",
                                                 start=iso(theo_exam), source="call_booking", patient_name="Theo Lindqvist",
                                                 now=bd(-11, 9, 40).timestamp()), "Theo's booking"))
    tap("theo", bd(-8, 11, 40), "happened")
    tap("theo", bd(-6, 9, 15), "started", note="Aligners ordered")

    # Ruby: paused by the desk.
    quote("ruby", bd(-7, 15, 50), phone=PHONES["ruby"])
    tap("ruby", bd(-4, 10, 20), "paused", note="Family travelling until December")

    # Finn: cancelled on a call with Katie, later marked lost.
    finn_exam = bd(-7, 15, 0)
    quote("finn", bd(-10, 12, 5), phone=PHONES["finn"], appt=("APPT-2262", finn_exam))
    at(bd(-8, 9, 10), lambda: need(leads.cancelled(PHONES["finn"], label(finn_exam), appointment_id="APPT-2262",
                                                   source="call_cancel", now=bd(-8, 9, 10).timestamp()), "Finn's cancel"))
    tap("finn", bd(-3, 14, 0), "lost", note="Chose another office")

    for _when, _n, fn in sorted(steps, key=lambda s: (s[0], s[1])):
        fn()

    ts = now.timestamp()
    rows = leads.list_leads(stage="", limit=2000, reveal=False, now=ts)
    assert len(rows) == len(Q), f"{len(rows)} leads, expected {len(Q)}"
    events = {}
    for r in rows:
        assert "***" in r["phone"], "a fixture phone left unmasked"
        events[r["lead_id"]] = leads.get_lead(r["lead_id"], reveal=False, now=ts)["events"]
    return {"now": ts, "tz": TZ_NAME, "leads": rows, "events": events, "summary": leads.summary(now=ts)}


# ---------------------------------------------------------------- what the backend answers to the taps

FILTERS = ("open", "missed_consult", "never_booked", *leads.STAGES, "", "nonsense")
SINGLE = [{"action": "happened"}, {"action": "started"}, {"action": "lost", "note": "Went elsewhere"},
          {"action": "paused"}, {"action": "reopen"}, {"action": "missed"}, {"action": "booked"},
          {"action": "booked", "slot_label": "Thu 9:00 AM"}, {"action": "booked", "slot_label": "thursday 9:00 am"},
          {"action": "booked", "slot_label": "2026-10-29T15:40"}, {"action": "booked", "slot_label": "2026-11-03T08:20:00-05:00"},
          {"action": "booked", "slot_label": "sometime next week"}, {"action": "booked", "slot_label": "Mon 6:05 PM"},
          {"action": "note", "note": "  Call after 4  "}, {"action": "note", "note": ""}, {"action": "note", "note": "x" * 520},
          {"action": " Lost "}, {"action": "dance"}]
CHAINS = [[{"action": "paused", "note": "Back in January"}, {"action": "reopen"}],
          [{"action": "lost"}, {"action": "reopen", "note": "Called back"}],
          [{"action": "booked", "slot_label": "Fri 7:40 AM"}, {"action": "missed"}, {"action": "paused"}, {"action": "reopen"}],
          [{"action": "happened"}, {"action": "started"}, {"action": "started"}, {"action": "lost"}],
          [{"action": "paused"}, {"action": "started"}], [{"action": "lost"}, {"action": "started"}]]


def actions(now: datetime) -> dict:
    """Every tap on every fixture lead, each on its own copy of the store, as the route answers it."""
    import shutil
    import sqlite3
    store = build(now)
    base = os.environ["LEADS_DB_PATH"]
    with sqlite3.connect(base) as c:
        c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
    ts = now.timestamp()
    lists = {f: [l["lead_id"] for l in leads.list_leads(stage=f, limit=2000, now=ts)] for f in FILTERS}
    lists["limit=3"] = [l["lead_id"] for l in leads.list_leads(stage="open", limit=3, now=ts)]
    revealed = {l["lead_id"]: l["phone"] for l in leads.list_leads(reveal=True, limit=2000, now=ts)}
    trials, n = [], 0
    for lead_id in [l["lead_id"] for l in store["leads"]] + ["Lnope"]:
        for steps in [[s] for s in SINGLE] + CHAINS:
            n += 1
            path = os.path.join(_tmp, f"trial-{n}.sqlite")
            shutil.copyfile(base, path)
            os.environ["LEADS_DB_PATH"] = path
            before = len((leads.get_lead(lead_id, now=ts) or {}).get("events", []))
            results = []
            for i, step in enumerate(steps):
                t = ts + 60 * (i + 1)
                action = str(step.get("action") or "").strip().lower()
                if action not in leads.COORDINATOR_ACTIONS:      # dash_api.lead_action's own check
                    results.append({"status": 422, "error": f"action must be one of {', '.join(leads.COORDINATOR_ACTIONS)}"})
                    continue
                try:
                    row = leads.coordinator(lead_id, action, who=WHO, note=str(step.get("note") or ""),
                                            slot_label=str(step.get("slot_label") or ""), now=t)
                except ValueError as e:
                    results.append({"status": 409, "error": str(e)})
                    continue
                if row is None:
                    results.append({"status": 404, "error": "no such lead"})
                    continue
                results.append({"status": 200, "lead": {**row, "phone": leads.mask(row["phone"])}})
            after = (leads.get_lead(lead_id, now=ts) or {}).get("events", [])
            trials.append({"lead_id": lead_id, "steps": steps, "results": results, "new_events": after[before:]})
            os.remove(path)
    os.environ["LEADS_DB_PATH"] = base
    return {"now": ts, "who": WHO, "lists": lists, "revealed": revealed, "trials": trials}


def main() -> None:
    status = json.load(open(OUT / "status.json"))
    fixture_now = datetime.fromtimestamp(status["now"], TZ)
    store = build(fixture_now)
    with open(OUT / "leads.json", "w") as f:
        json.dump(store, f, indent=1, ensure_ascii=False)
        f.write("\n")
    print(f"leads.json: {len(store['leads'])} leads as of {fixture_now:%a %Y-%m-%d %H:%M:%S %Z}  {store['summary']}")

    monday = fixture_now.date() - timedelta(days=fixture_now.weekday())
    week = []
    for i in range(7):
        d = monday + timedelta(days=i)
        s = build(datetime(d.year, d.month, d.day, 21, 10, 0, tzinfo=TZ))
        week.append(s)
        print(f"  week[{i}] {d:%a %Y-%m-%d}: {s['summary']['by_stage']}  missed {s['summary']['missed_consult']}"
              f"  never booked {s['summary']['never_booked']}")
    with open(OUT / "leads-week.json", "w") as f:
        json.dump({"tz": TZ_NAME, "days": week}, f, separators=(",", ":"), ensure_ascii=False)
        f.write("\n")

    acts = actions(fixture_now)
    (HERE / "fixtures").mkdir(exist_ok=True)
    with open(HERE / "fixtures" / "leads-actions.json", "w") as f:
        json.dump(acts, f, separators=(",", ":"), ensure_ascii=False)
        f.write("\n")
    by = {}
    for t in acts["trials"]:
        for r in t["results"]:
            by[r["status"]] = by.get(r["status"], 0) + 1
    print(f"leads-actions.json: {len(acts['trials'])} trials, answers by status {dict(sorted(by.items()))}")


if __name__ == "__main__":
    main()
